```tsx
import "./ChipFilter.css";

export interface ChipOption<T extends string = string> {
  readonly value: T;
  readonly label: string;
}

export interface ChipFilterProps<T extends string = string> {
  readonly label: string;
  readonly options: readonly ChipOption<T>[];
  readonly selected: readonly T[];
  readonly onToggle: (value: T) => void;
}

export function ChipFilter<T extends string = string>({
  label,
  options,
  selected,
  onToggle,
}: ChipFilterProps<T>) {
  const selectedSet = new Set<T>(selected);

  return (
    <fieldset className="chip-filter">
      <legend className="chip-filter__legend">{label}</legend>
      <div className="chip-filter__chips">
        {options.map((option) => {
          const isOn = selectedSet.has(option.value);
          const className = isOn
            ? "chip-filter__chip chip-filter__chip--on"
            : "chip-filter__chip";

          return (
            <button
              key={option.value}
              type="button"
              className={className}
              aria-pressed={isOn}
              onClick={() => onToggle(option.value)}
            >
              <span className="chip-filter__indicator" aria-hidden="true" />
              <span className="chip-filter__text">{option.label}</span>
            </button>
          );
        })}
      </div>
    </fieldset>
  );
}
