/* ChipFilter — Myelin day/night theming via CSS custom properties.
   Night applies when <html data-theme="night"> is set, or when the
   OS prefers dark and no explicit theme has been chosen. */

:root {
  --chip-filter-legend: #4a5560;
  --chip-filter-text: #1f2a33;
  --chip-filter-border: #c9d2d9;
  --chip-filter-bg: #f6f8f9;
  --chip-filter-bg-hover: #eaf0f3;
  --chip-filter-accent: #2c7a72;
  --chip-filter-accent-text: #ffffff;
  --chip-filter-focus: #2c7a72;
  --chip-filter-indicator-off: #9aa7b1;
}

[data-theme="night"] {
  --chip-filter-legend: #9aa9b5;
  --chip-filter-text: #e3eaef;
  --chip-filter-border: #33414d;
  --chip-filter-bg: #18222b;
  --chip-filter-bg-hover: #213039;
  --chip-filter-accent: #5fb8ad;
  --chip-filter-accent-text: #0e1820;
  --chip-filter-focus: #8fd6cc;
  --chip-filter-indicator-off: #5d6d7a;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="day"]) {
    --chip-filter-legend: #9aa9b5;
    --chip-filter-text: #e3eaef;
    --chip-filter-border: #33414d;
    --chip-filter-bg: #18222b;
    --chip-filter-bg-hover: #213039;
    --chip-filter-accent: #5fb8ad;
    --chip-filter-accent-text: #0e1820;
    --chip-filter-focus: #8fd6cc;
    --chip-filter-indicator-off: #5d6d7a;
  }
}

.chip-filter {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
}

.chip-filter__legend {
  padding: 0;
  margin-bottom: 0.5rem;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--chip-filter-legend);
}

.chip-filter__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.chip-filter__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.5rem;
  padding: 0.5rem 0.875rem;
  border: 1px solid var(--chip-filter-border);
  border-radius: 999px;
  background: var(--chip-filter-bg);
  color: var(--chip-filter-text);
  font: inherit;
  font-size: 0.9375rem;
  line-height: 1;
  cursor: pointer;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    color 160ms ease;
  -webkit-tap-highlight-color: transparent;
}

.chip-filter__chip:hover {
  background: var(--chip-filter-bg-hover);
}

.chip-filter__chip:focus-visible {
  outline: 2px solid var(--chip-filter-focus);
  outline-offset: 2px;
}

.chip-filter__chip--on {
  background: var(--chip-filter-accent);
  border-color: var(--chip-filter-accent);
  color: var(--chip-filter-accent-text);
  font-weight: 600;
}

.chip-filter__chip--on:hover {
  background: var(--chip-filter-accent);
  filter: brightness(1.05);
}

/* Non-color state cue: a dot that fills in when the chip is on. */
.chip-filter__indicator {
  flex: 0 0 auto;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  border: 1.5px solid var(--chip-filter-indicator-off);
  background: transparent;
  transition: background-color 160ms ease, border-color 160ms ease;
}

.chip-filter__chip--on .chip-filter__indicator {
  border-color: currentColor;
  background: currentColor;
}

@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip,
  .chip-filter__indicator {
    transition: none;
  }
}
